import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Stack;

public class Test {
    static PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    int R, C;
    List<long[]> rows;
    int[] cntA = new int[61], cntB = new int[61];
    long best = Long.MAX_VALUE;
    String str;
    Map<Long, Long> cache = new HashMap<>();
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

    static class Frame {
        long x, y;
        int v1, v2;
        Frame(long x, long y, int v1, int v2) { this.x = x; this.y = y; this.v1 = v1; this.v2 = v2; }
    }

    public static void main(String[] args) {
        Test te = new Test();
        te.start();
        writer.flush();
    }

    int readInt() {
        int ans = 0;
        boolean neg = false;
        try {
            boolean start = false;
            int c;
            while ((c = br.read()) != -1) {
                if (c == '-') {
                    start = true;
                    neg = true;
                    continue;
                } else if (c >= '0' && c <= '9') {
                    start = true;
                    ans = ans * 10 + c - '0';
                } else if (start) break;
            }
        } catch (IOException e) {}
        return neg ? -ans : ans;
    }

    long readLong() {
        long ans = 0;
        boolean neg = false;
        try {
            boolean start = false;
            int c;
            while ((c = br.read()) != -1) {
                if (c == '-') {
                    start = true;
                    neg = true;
                    continue;
                } else if (c >= '0' && c <= '9') {
                    start = true;
                    ans = ans * 10 + c - '0';
                } else if (start) break;
            }
        } catch (IOException e) {}
        return neg ? -ans : ans;
    }

    String readString() {
        StringBuilder b = new StringBuilder();
        try {
            boolean start = false;
            int c;
            while ((c = br.read()) != -1) {
                if (!Character.isWhitespace(c)) {
                    start = true;
                    b.append((char) c);
                } else if (start) break;
            }
        } catch (IOException e) {}
        return b.toString();
    }

    void computeBinomial(int maxN) {
        rows = new ArrayList<>();
        for (int i = 0; i <= maxN; i++) {
            long[] row = new long[i + 1];
            row[0] = row[i] = 1;
            for (int j = 1; j < i; j++) {
                row[j] = rows.get(i - 1)[j - 1] + rows.get(i - 1)[j];
            }
            rows.add(row);
        }
    }

    void dfs(long x, long y, int v1, int v2) {
        Stack<Frame> stack = new Stack<>();
        stack.push(new Frame(x, y, v1, v2));
        while (!stack.isEmpty()) {
            Frame f = stack.pop();
            long diff = Math.abs(f.x - f.y);
            if (best <= 1 || diff - rows.get(f.v1)[R] * rows.get(f.v2)[R] >= best) continue;
            if (f.v1 == R - 1 && f.v2 == R - 1) {
                if (diff < best) best = diff;
                continue;
            }
            if (f.v2 >= R) {
                long cur = rows.get(f.v2)[R] - rows.get(f.v2 - 1)[R];
                long other = rows.get(f.v1)[R];
                stack.push(new Frame(f.x + cur * other, f.y, f.v1, f.v2 - 1));
            }
            if (f.v1 >= R) {
                long cur = rows.get(f.v1)[R] - rows.get(f.v1 - 1)[R];
                long other = rows.get(f.v2)[R];
                stack.push(new Frame(f.x, f.y + cur * other, f.v1 - 1, f.v2));
            }
        }
    }

    long solve(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (diff - rows.get(v1)[R] * rows.get(v2)[R] > best) return 0;
        long key = x * 10000 + v1 * 100 + v2;
        Long v = cache.get(key);
        if (v != null) return v;
        if (v1 < R || v2 < R) {
            if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
                int sum = v1 + v2;
                v1 -= cntA[sum];
                v2 -= cntB[sum];
                return rows.get(v1 + v2)[v1];
            }
            return 0;
        }
        long ans = 0;
        char c = str.charAt(v1 + v2 - 1);
        if (c != 'B') {
            long cur = rows.get(v1)[R] - rows.get(v1 - 1)[R];
            long other = rows.get(v2)[R];
            ans += solve(x, y + cur * other, v1 - 1, v2);
        }
        if (c != 'A') {
            long cur = rows.get(v2)[R] - rows.get(v2 - 1)[R];
            long other = rows.get(v1)[R];
            ans += solve(x + cur * other, y, v1, v2 - 1);
        }
        cache.put(key, ans);
        return ans;
    }

    void start() {
        R = readInt();
        C = readInt();
        int maxN = 2 * (R + C);
        computeBinomial(maxN);
        long x = 0, y = 0;
        int v1 = R + C, v2 = R + C;
        while (v1 >= R && v2 >= R)
            if (x > y) {
                long cur = rows.get(v1)[R] - rows.get(v1 - 1)[R];
                long other = rows.get(v2)[R];
                y += cur * other;
                v1--;
            } else {
                long cur = rows.get(v2)[R] - rows.get(v2 - 1)[R];
                long other = rows.get(v1)[R];
                x += cur * other;
                v2--;
            }
        best = Math.abs(x - y);
        dfs(0, 0, R + C, R + C);
        str = readString();
        for (int i = 0; i < 2 * (R + C); i++) {
            cntA[i + 1] = cntA[i] + (str.charAt(i) == 'A' ? 1 : 0);
            cntB[i + 1] = cntB[i] + (str.charAt(i) == 'B' ? 1 : 0);
        }
        long ans = solve(0, 0, R + C, R + C);
        writer.println(ans);
    }
}
